    pmb->pscalars->sbvar.var_cc = &(pmb->pscalars->s);
    if (pmb->pmy_mesh->multilevel) {
      pmb->pscalars->sbvar.coarse_buf = &(pmb->pscalars->coarse_s_);
    }
    pmb->pscalars->sbvar.SendBoundaryBuffers();
