// EquationOfState constructor

EquationOfState::EquationOfState(MeshBlock *pmb, ParameterInput *pin) :
    pmy_block_(pmb),
    gamma_{pin->GetReal("hydro", "gamma")},
    density_floor_{pin->GetOrAddReal("hydro", "dfloor", std::sqrt(1024*float_min))},
    pressure_floor_{pin->GetOrAddReal("hydro", "pfloor", std::sqrt(1024*float_min))},
    scalar_floor_{pin->GetOrAddReal("hydro", "sfloor", std::sqrt(1024*float_min))} {}

//----------------------------------------------------------------------------------------
//! \fn void EquationOfState::ConservedToPrimitive(AthenaArray<Real> &cons,
//!   const AthenaArray<Real> &prim_old, const FaceField &b,
//!   AthenaArray<Real> &prim, AthenaArray<Real> &bcc, Coordinates *pco,
//!   int il, int iu, int jl, int ju, int kl, int ku);
//! \brief For the Hydro, converts conserved into primitive variables in adiabatic MHD.
//!  For the Field, computes cell-centered from face-centered magnetic field.

void EquationOfState::ConservedToPrimitive(
    AthenaArray<Real> &cons, const AthenaArray<Real> &prim_old, const FaceField &b,
    AthenaArray<Real> &prim, AthenaArray<Real> &bcc,
    Coordinates *pco, int il, int iu, int jl, int ju, int kl, int ku) {
  Real gm1 = GetGamma() - 1.0;

  pmy_block_->pfield->CalculateCellCenteredField(b,bcc,pco,il,iu,jl,ju,kl,ku);

  for (int k=kl; k<=ku; ++k) {
    for (int j=jl; j<=ju; ++j) {
#pragma omp simd
      for (int i=il; i<=iu; ++i) {
        Real& u_d  = cons(IDN,k,j,i);
        Real& u_m1 = cons(IM1,k,j,i);
        Real& u_m2 = cons(IM2,k,j,i);
        Real& u_m3 = cons(IM3,k,j,i);
        Real& u_e  = cons(IEN,k,j,i);

        Real& w_d  = prim(IDN,k,j,i);
        Real& w_vx = prim(IVX,k,j,i);
        Real& w_vy = prim(IVY,k,j,i);
        Real& w_vz = prim(IVZ,k,j,i);
        Real& w_p  = prim(IPR,k,j,i);

        // apply density floor, without changing momentum or energy
        if (!(u_d > density_floor_) || !std::isfinite(u_d)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ConservedToPrimitive","u_d","cell_centered_conserved",k,j,i,u_d,u_e,NAN,NAN,NAN,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: u_d"); }
  u_d = (u_d > density_floor_) ?  u_d : density_floor_;
        w_d = u_d;

        Real di = 1.0/u_d;
        w_vx = u_m1*di;
        w_vy = u_m2*di;
        w_vz = u_m3*di;

        const Real& bcc1 = bcc(IB1,k,j,i);
        const Real& bcc2 = bcc(IB2,k,j,i);
        const Real& bcc3 = bcc(IB3,k,j,i);

        Real pb = 0.5*(SQR(bcc1) + SQR(bcc2) + SQR(bcc3));
        Real e_k = 0.5*di*(SQR(u_m1) + SQR(u_m2) + SQR(u_m3));
        w_p = gm1*(u_e - e_k - pb);

        // apply pressure floor, correct total energy
        if (!(w_p > pressure_floor_) || !std::isfinite(w_p)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ConservedToPrimitive","u_e","cell_centered_conserved",k,j,i,u_d,u_e,e_k,pb,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: u_e"); }
  u_e = (w_p > pressure_floor_) ?  u_e : ((pressure_floor_/gm1) + e_k + pb);
        if (!(w_p > pressure_floor_) || !std::isfinite(w_p)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ConservedToPrimitive","w_p","cell_centered_conserved",k,j,i,u_d,u_e,e_k,pb,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: w_p"); }
  w_p = (w_p > pressure_floor_) ?  w_p : pressure_floor_;
      }
    }
  }

  return;
}

//----------------------------------------------------------------------------------------
//! \fn void EquationOfState::PrimitiveToConserved(const AthenaArray<Real> &prim,
//!           const AthenaArray<Real> &bc, AthenaArray<Real> &cons, Coordinates *pco,
//!           int il, int iu, int jl, int ju, int kl, int ku);
//! \brief Converts primitive variables into conservative variables
//!        Note that this function assumes cell-centered fields are already calculated

void EquationOfState::PrimitiveToConserved(
    const AthenaArray<Real> &prim, const AthenaArray<Real> &bc,
    AthenaArray<Real> &cons, Coordinates *pco,
    int il, int iu, int jl, int ju, int kl, int ku) {
  Real igm1 = 1.0/(GetGamma() - 1.0);

  for (int k=kl; k<=ku; ++k) {
    for (int j=jl; j<=ju; ++j) {
#pragma omp simd
      for (int i=il; i<=iu; ++i) {
        Real& u_d  = cons(IDN,k,j,i);
        Real& u_m1 = cons(IM1,k,j,i);
        Real& u_m2 = cons(IM2,k,j,i);
        Real& u_m3 = cons(IM3,k,j,i);
        Real& u_e  = cons(IEN,k,j,i);

        const Real& w_d  = prim(IDN,k,j,i);
        const Real& w_vx = prim(IVX,k,j,i);
        const Real& w_vy = prim(IVY,k,j,i);
        const Real& w_vz = prim(IVZ,k,j,i);
        const Real& w_p  = prim(IPR,k,j,i);

        const Real& bcc1 = bc(IB1,k,j,i);
        const Real& bcc2 = bc(IB2,k,j,i);
        const Real& bcc3 = bc(IB3,k,j,i);

        u_d = w_d;
        u_m1 = w_vx*w_d;
        u_m2 = w_vy*w_d;
        u_m3 = w_vz*w_d;
        u_e = w_p*igm1 + 0.5*(w_d*(SQR(w_vx) + SQR(w_vy) + SQR(w_vz))
                              + (SQR(bcc1) + SQR(bcc2) + SQR(bcc3)));
      }
    }
  }

  return;
}

//----------------------------------------------------------------------------------------
//! \fn Real EquationOfState::SoundSpeed(Real prim[NHYDRO])
//! \brief returns adiabatic sound speed given vector of primitive variables
Real EquationOfState::SoundSpeed(const Real prim[NHYDRO]) {
  return std::sqrt(GetGamma()*prim[IPR]/prim[IDN]);
}

//----------------------------------------------------------------------------------------
//! \fn Real EquationOfState::FastMagnetosonicSpeed(const Real prim[], const Real bx)
//! \brief returns fast magnetosonic speed given vector of primitive variables
//! Note the formula for (C_f)^2 is positive definite, so this func never returns a NaN
Real EquationOfState::FastMagnetosonicSpeed(const Real prim[(NWAVE)], const Real bx) {
  Real asq = GetGamma()*prim[IPR];
  Real vaxsq = bx*bx;
  Real ct2 = (prim[IBY]*prim[IBY] + prim[IBZ]*prim[IBZ]);
  Real qsq = vaxsq + ct2 + asq;
  Real tmp = vaxsq + ct2 - asq;
  return std::sqrt(0.5*(qsq + std::sqrt(tmp*tmp + 4.0*asq*ct2))/prim[IDN]);
}

//---------------------------------------------------------------------------------------
//! \fn void EquationOfState::ApplyPrimitiveFloors(AthenaArray<Real> &prim, int k, int j,
//!                                                 int i)
//! \brief Apply density and pressure floors to reconstructed L/R cell interface states
void EquationOfState::ApplyPrimitiveFloors(AthenaArray<Real> &prim, int k, int j, int i) {
  Real& w_d  = prim(IDN,i);
  Real& w_p  = prim(IPR,i);

  // apply density floor
  if (!(w_d > density_floor_) || !std::isfinite(w_d)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ApplyPrimitiveFloors","w_d","reconstructed_primitive_interface",k,j,i,w_d,NAN,NAN,NAN,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: w_d"); }
  w_d = (w_d > density_floor_) ?  w_d : density_floor_;
  // apply pressure floor
  if (!(w_p > pressure_floor_) || !std::isfinite(w_p)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ApplyPrimitiveFloors","w_p","reconstructed_primitive_interface",k,j,i,w_d,NAN,NAN,NAN,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: w_p"); }
  w_p = (w_p > pressure_floor_) ?  w_p : pressure_floor_;

  return;
}

//----------------------------------------------------------------------------------------
//! \fn void EquationOfState::ApplyPrimitiveConservedFloors(AthenaArray<Real> &prim,
//!           AthenaArray<Real> &cons, FaceField &b, int k, int j, int i) {
//! \brief Apply pressure (prim) floor and correct energy (cons) (typically after W(U))
void EquationOfState::ApplyPrimitiveConservedFloors(
    AthenaArray<Real> &prim, AthenaArray<Real> &cons, AthenaArray<Real> &bcc,
    int k, int j, int i) {
  Real gm1 = GetGamma() - 1.0;
  Real& w_d  = prim(IDN,k,j,i);
  Real& w_p  = prim(IPR,k,j,i);

  Real& u_d  = cons(IDN,k,j,i);
  Real& u_e  = cons(IEN,k,j,i);
  const Real& bcc1 = bcc(IB1,k,j,i);
  const Real& bcc2 = bcc(IB2,k,j,i);
  const Real& bcc3 = bcc(IB3,k,j,i);

  // apply (prim) density floor, without changing momentum or energy
  if (!(w_d > density_floor_) || !std::isfinite(w_d)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ApplyPrimitiveConservedFloors","w_d","cell_average_primitive_conserved",k,j,i,w_d,u_e,NAN,NAN,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: w_d"); }
  w_d = (w_d > density_floor_) ?  w_d : density_floor_;
  // ensure cons density matches
  u_d = w_d;

  Real pb = 0.5*(SQR(bcc1) + SQR(bcc2) + SQR(bcc3));
  Real e_k = 0.5*w_d*(SQR(prim(IVX,k,j,i)) + SQR(prim(IVY,k,j,i))
                      + SQR(prim(IVZ,k,j,i)));
  // apply pressure floor, correct total energy
  if (!(w_p > pressure_floor_) || !std::isfinite(w_p)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ApplyPrimitiveConservedFloors","u_e","cell_average_primitive_conserved",k,j,i,w_d,u_e,e_k,pb,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: u_e"); }
  u_e = (w_p > pressure_floor_) ?
        u_e : ((pressure_floor_/gm1) + pb + e_k);
  if (!(w_p > pressure_floor_) || !std::isfinite(w_p)) { X3ICTStrictAbortDiagnostic(pmy_block_,"ApplyPrimitiveConservedFloors","w_p","cell_average_primitive_conserved",k,j,i,w_d,u_e,e_k,pb,w_p,density_floor_,pressure_floor_,gamma_); throw std::runtime_error("Athena CT strict pre-floor abort: w_p"); }
  w_p = (w_p > pressure_floor_) ?
        w_p : pressure_floor_;

  return;
}

#pragma once
#include <complex>
#include <functional>
#include "boundary_parser.hpp"
namespace x3ict {
using C=std::complex<double>;
// Mixed-radix Cooley-Tukey; prime factors use a direct base transform.
inline std::vector<C> fft(const std::vector<C>&a,int sign){
 int n=a.size(),p=2;while(p<n&&n%p)++p;int q=n/p;std::vector<C>out(n);
 if(p==n){for(int k=0;k<n;++k)for(int j=0;j<n;++j)out[k]+=a[j]*std::polar(1.,sign*2*XPI*j*k/n);return out;}
 std::vector<std::vector<C>> sub(p);for(int j=0;j<p;++j){std::vector<C>z(q);for(int l=0;l<q;++l)z[l]=a[j+p*l];sub[j]=fft(z,sign);}
 for(int k=0;k<n;++k)for(int j=0;j<p;++j)out[k]+=sub[j][k%q]*std::polar(1.,sign*2*XPI*j*k/n);return out;
}
struct Surface {
 int n,m;double r,dt,dp;std::vector<double>w,st;
 std::vector<double> et,ep,br0,br1;double removed_mean=0,maximum_residual=0,maximum_relative_residual=0;
 Surface(int n_,int m_,double r_):n(n_),m(m_),r(r_),dt(XPI/n),dp(2*XPI/m),w(n),st(n),et(n*m),ep((n+1)*m){for(int j=0;j<n;++j){w[j]=std::cos(j*dt)-std::cos((j+1)*dt);st[j]=std::sin((j+.5)*dt);}}
 int ix(int j,int k)const{return j*m+(k%m+m)%m;}
 double curl(const std::vector<double>&a,const std::vector<double>&b,int j,int k)const{
  return (std::sin((j+1)*dt)*b[ix(j+1,k)]-std::sin(j*dt)*b[ix(j,k)])/(r*w[j])-dt*(a[ix(j,k+1)]-a[ix(j,k)])/(r*w[j]*dp);
 }
 void fit(const std::vector<double>&b0,const std::vector<double>&b1,double h,double omega){
  if(!(h>0))throw std::runtime_error("surface interval must be positive");br0=b0;br1=b1;std::vector<double>rhs(n*m);std::fill(ep.begin(),ep.end(),0.);
  for(int j=0;j<n;++j)for(int k=0;k<m;++k)et[ix(j,k)]=-omega*r*st[j]*.25*(b0[ix(j,k-1)]+b0[ix(j,k)]+b1[ix(j,k-1)]+b1[ix(j,k)]);
  double mean=0;for(int j=0;j<n;++j)for(int k=0;k<m;++k){rhs[ix(j,k)]=(b1[ix(j,k)]-b0[ix(j,k)])/h+curl(et,ep,j,k);mean+=rhs[ix(j,k)]*w[j]/(2*m);}removed_mean=mean;
  std::vector<std::vector<C>> f(n,std::vector<C>(m));for(int j=0;j<n;++j){for(int k=0;k<m;++k)f[j][k]=(rhs[ix(j,k)]-mean)*r*r;f[j]=fft(f[j],-1);}
  for(int mode=0;mode<m;++mode){std::vector<double>a(n),d(n),c(n);std::vector<C>z(n);double lam=4*std::pow(std::sin(XPI*mode/m),2)/(dp*dp);
   for(int j=0;j<n;++j){a[j]=std::sin(j*dt)/(w[j]*dt);c[j]=std::sin((j+1)*dt)/(w[j]*dt);d[j]=-a[j]-c[j]-dt*lam/(w[j]*st[j]);z[j]=f[j][mode];}
   if(mode==0){d[0]=1;c[0]=0;z[0]=0;}
   for(int j=1;j<n;++j){double t=a[j]/d[j-1];d[j]-=t*c[j-1];z[j]-=t*z[j-1];}
   z[n-1]/=d[n-1];for(int j=n-2;j>=0;--j)z[j]=(z[j]-c[j]*z[j+1])/d[j];for(int j=0;j<n;++j)f[j][mode]=z[j];
  }
  std::vector<double>u(n*m);for(int j=0;j<n;++j){auto z=fft(f[j],1);for(int k=0;k<m;++k)u[ix(j,k)]=z[k].real()/m;}
  for(int j=0;j<n;++j)for(int k=0;k<m;++k)et[ix(j,k)]+=(u[ix(j,k)]-u[ix(j,k-1)])/(r*st[j]*dp);
  for(int j=1;j<n;++j)for(int k=0;k<m;++k)ep[ix(j,k)]=-(u[ix(j,k)]-u[ix(j-1,k)])/(r*dt);
  double mx=0,scale=0;for(int j=0;j<n;++j)for(int k=0;k<m;++k){double q=(b1[ix(j,k)]-b0[ix(j,k)])/h;mx=std::max(mx,std::abs(q+curl(et,ep,j,k)));scale=std::max(scale,std::abs(q));}maximum_residual=std::max(maximum_residual,mx);maximum_relative_residual=std::max(maximum_relative_residual,mx/(scale+1e-99));
 }
};
// Exact angular area average of the parser's clamped-latitude, periodic-longitude
// piecewise-bilinear Br. Scalar velocity/thermodynamics retain parser semantics.
struct Target {
 const Boundary&b;Surface&s;std::string mode;double amplitude,frequency;std::vector<double>latmean;double last_removed_mean=0;
 Target(const Boundary&b_,Surface&s_,std::string mode_,double amp=3.,double freq=2*XPI):b(b_),s(s_),mode(mode_),amplitude(amp),frequency(freq){
  if(mode!="real"||!b.angular)return;latmean.assign((size_t)b.nt*s.n*b.nl,0.);
  for(int j=0;j<s.n;++j){double lo=XPI/2-(j+1)*s.dt,hi=XPI/2-j*s.dt;std::vector<double>weights(b.na,0.);double x=lo;
   while(x<hi-1e-14){int a;double y;bool clamp=false;
    if(x<b.lats.front()-1e-14){a=0;y=std::min(hi,b.lats.front());clamp=true;}
    else if(x>=b.lats.back()-1e-14){a=b.na-1;y=hi;clamp=true;}
    else{a=std::upper_bound(b.lats.begin(),b.lats.end(),x+1e-14)-b.lats.begin()-1;y=std::min(hi,b.lats[a+1]);}
    double integral=std::sin(y)-std::sin(x);if(clamp)weights[a]+=integral;else{double z=(y*std::sin(y)+std::cos(y)-x*std::sin(x)-std::cos(x)-b.lats[a]*integral)/(b.lats[a+1]-b.lats[a]);weights[a]+=integral-z;weights[a+1]+=z;}x=y;
   }
   for(int t=0;t<b.nt;++t)for(int l=0;l<b.nl;++l)for(int a=0;a<b.na;++a)latmean[((size_t)t*s.n+j)*b.nl+l]+=weights[a]*b.values[((size_t)t*b.na+a)*b.nl+l][2]/s.w[j];
  }
 }
 std::vector<double> at(double time){
  std::vector<double>out(s.n*s.m);double unit=1e-9/BUNIT/(s.r*s.r);
  if(mode!="real"){
   for(int j=0;j<s.n;++j)for(int k=0;k<s.m;++k){double avgcos=.5*(std::pow(std::sin((j+1)*s.dt),2)-std::pow(std::sin(j*s.dt),2))/s.w[j];double avgsin=(.5*s.dt-.25*(std::sin(2*(j+1)*s.dt)-std::sin(2*j*s.dt)))/s.w[j];
    if(mode=="uniform")out[s.ix(j,k)]=amplitude*1e-9/BUNIT*avgcos;
    else if(mode=="radial")out[s.ix(j,k)]=amplitude*unit;
    else out[s.ix(j,k)]=amplitude*unit*(1+.2*std::sin(frequency*time))*(avgcos+.3*avgsin*2*std::sin(s.dp/2)/s.dp*std::cos((k+.5)*s.dp-b.rotation*time));
   }return out;
  }
  if(!b.angular){std::fill(out.begin(),out.end(),b.sample(time,0,0)[2]*unit);return out;}
  int t=0;double ft=0;if(time>=b.times.back()){t=b.nt-2;ft=1;}else if(time>b.times.front()){t=std::upper_bound(b.times.begin(),b.times.end(),time)-b.times.begin()-1;ft=(time-b.times[t])/(b.times[t+1]-b.times[t]);}
  if(b.nt==1){t=0;ft=0;}int t1=std::min(t+1,b.nt-1);
  auto value=[&](int j,int l){return (1-ft)*latmean[((size_t)t*s.n+j)*b.nl+l]+ft*latmean[((size_t)t1*s.n+j)*b.nl+l];};
  for(int k=0;k<s.m;++k){double lo=wrap(k*s.dp-b.rotation*(time-b.epoch)-b.offset),hi=lo+s.dp,x=lo;
   while(x<hi-1e-14){double xx=wrap(x+1e-14);auto q=std::upper_bound(b.lons.begin(),b.lons.end(),xx);int l=q==b.lons.begin()?b.nl-1:int(q-b.lons.begin()-1),l1=(l+1)%b.nl;double left=b.lons[l],right=b.lons[l1];if(l1==0)right+=2*XPI;if(xx<left)xx+=2*XPI;double dx=std::min(hi-x,right-xx);if(dx<1e-13){x+=1e-13;continue;}double f0=(xx-left)/(right-left),f1=(xx+dx-left)/(right-left),f=.5*(f0+f1);
    for(int j=0;j<s.n;++j)out[s.ix(j,k)]+=dx*((1-f)*value(j,l)+f*value(j,l1))/s.dp;x+=dx;
   }
  }
  double mean=0;for(int j=0;j<s.n;++j)for(int k=0;k<s.m;++k)mean+=out[s.ix(j,k)]*s.w[j]/(2*s.m);last_removed_mean=mean*b.magnetic_scale;
  for(auto&z:out)z=(z-mean)*b.magnetic_scale*unit;return out;
 }
};
}

